package com.film.one;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import com.bumptech.glide.Glide;import org.json.*;import java.util.*;import java.net.*;import java.io.*;

public class DetailActivity extends Activity {
    final int BG=Color.rgb(7,9,14),PANEL=Color.rgb(18,21,29),WHITE=Color.WHITE,MUTED=Color.rgb(158,166,180),BLUE=Color.rgb(0,174,255); MainActivity.Movie movie; SharedPreferences prefs;
    int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;} GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("film_one",MODE_PRIVATE);try{movie=MainActivity.Movie.fromJson(new JSONObject(getIntent().getStringExtra("movie")));}catch(Exception e){finish();return;}build();}
    void build(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);sc.addView(root);ImageView back=new ImageView(this);back.setImageResource(android.R.drawable.ic_menu_revert);back.setPadding(dp(16),dp(12),dp(16),dp(12));back.setColorFilter(Color.WHITE);back.setBackgroundColor(Color.argb(100,0,0,0));FrameLayout hero=new FrameLayout(this);ImageView backdrop=new ImageView(this);backdrop.setScaleType(ImageView.ScaleType.CENTER_CROP);if(!movie.backdrop.isEmpty())Glide.with(this).load(movie.backdrop).into(backdrop);hero.addView(backdrop,new FrameLayout.LayoutParams(-1,dp(260)));hero.addView(back,new FrameLayout.LayoutParams(dp(60),dp(60)));back.setOnClickListener(v->finish());root.addView(hero);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),dp(16),dp(16),dp(28));LinearLayout row=new LinearLayout(this);ImageView poster=new ImageView(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);if(!movie.poster.isEmpty())Glide.with(this).load(movie.poster).into(poster);row.addView(poster,new LinearLayout.LayoutParams(dp(126),dp(188)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(14),0,0,0);TextView title=tv(movie.title,24,WHITE);title.setTypeface(null,1);info.addView(title);info.addView(tv(movie.originalTitle,13,MUTED));info.addView(tv(movie.year+"  •  "+(movie.type.equals("tv")||movie.type.equals("series")?"Сериал":"Фильм"),13,MUTED));info.addView(tv("★ "+movie.rating,14,Color.rgb(255,205,70)));if(!movie.genre.isEmpty())info.addView(tv(movie.genre,13,MUTED));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));content.addView(row);TextView desc=tv(movie.overview,15,WHITE);desc.setPadding(0,dp(18),0,dp(16));content.addView(desc);Button watch=new Button(this);watch.setText("▶  Смотреть");watch.setTextColor(WHITE);watch.setBackground(bg(BLUE,22));content.addView(watch,new LinearLayout.LayoutParams(-1,dp(52)));watch.setOnClickListener(v->{if(movie.videoUrl==null||movie.videoUrl.trim().isEmpty()){new AlertDialog.Builder(this).setTitle("Видео недоступно").setMessage("Для этого материала пока не указан разрешённый video source.").setPositiveButton("OK",null).show();}else{saveHistory();Intent i=new Intent(this,PlayerActivity.class);i.putExtra("title",movie.title);i.putExtra("video_url",movie.videoUrl);startActivity(i);}});Button fav=new Button(this);Set<String> f=prefs.getStringSet("favorites",new HashSet<>());boolean is=f.contains(movie.id);fav.setText(is?"♥  Удалить из избранного":"♡  В избранное");fav.setOnClickListener(v->{try{JSONArray a=new JSONArray(prefs.getString("favorite_items","[]"));JSONArray out=new JSONArray();boolean removed=false;for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);if(x.optString("id").equals(movie.id)){removed=true;continue;}out.put(x);}if(!removed)out.put(movie.toJson());fav.setText(removed?"♡  В избранное":"♥  Удалить из избранного");prefs.edit().putString("favorite_items",out.toString()).apply();}catch(Exception ignored){}});content.addView(fav,new LinearLayout.LayoutParams(-1,dp(52)));if(movie.type.equals("tv")||movie.type.equals("series")){TextView seasons=tv("Загрузка сезонов…",14,MUTED);content.addView(seasons,new LinearLayout.LayoutParams(-1,dp(70)));loadSeasons(seasons);}
root.addView(content);setContentView(sc);}

    void loadSeasons(TextView target){try{String cfg=readAsset("config.json");String api=new JSONObject(cfg).optString("api_base_url","");if(api.isEmpty()||movie.tmdbId.isEmpty()){target.setText("Сезоны будут доступны после подключения catalog API.");return;}new Thread(()->{try{URL u=new URL(api+"/api/title?type=tv&id="+URLEncoder.encode(movie.tmdbId,"UTF-8"));HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);String s=read(c.getInputStream());JSONObject o=new JSONObject(s);JSONArray a=o.optJSONArray("seasons");StringBuilder b=new StringBuilder("Сезоны\n");if(a!=null)for(int i=0;i<a.length();i++){JSONObject z=a.getJSONObject(i);b.append("Сезон ").append(z.optInt("season_number")).append(" — ").append(z.optInt("episode_count")).append(" серий\n");}runOnUiThread(()->target.setText(b.toString()));}catch(Exception e){runOnUiThread(()->target.setText("Не удалось загрузить сезоны."));}}).start();}catch(Exception e){target.setText("Не удалось загрузить сезоны.");}}
    String readAsset(String n)throws Exception{InputStream in=getAssets().open(n);ByteArrayOutputStream o=new ByteArrayOutputStream();byte[]b=new byte[4096];int z;while((z=in.read(b))!=-1)o.write(b,0,z);return o.toString("UTF-8");}
    String read(InputStream in)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[]b=new byte[8192];int z;while((z=in.read(b))!=-1)o.write(b,0,z);return o.toString("UTF-8");}
    void saveHistory(){String h=prefs.getString("history","");String line=movie.title+" • "+movie.year;h=line+(h.isEmpty()?"":"\n"+h.replace(line+"\n","").replace(line,""));String[]a=h.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(20,a.length);i++){if(i>0)b.append('\n');b.append(a[i]);}prefs.edit().putString("history",b.toString()).apply();}
}
